import {enumRules} from './options.js';
import {unzipSync,strFromU8} from './vendor/fflate.module.js';
import {defaults} from './avatar.js';import{convertSourceState}from'./source-settings.js';import{validateState}from'./mmd.js';
export async function readProject(file){if(file.size>32*1024*1024)throw new Error('프로젝트 파일은 32MB 이내로 선택해 주세요.');let json;const ext=file.name.split('.').pop().toLowerCase();if(ext==='zip'){const files=unzipSync(new Uint8Array(await file.arrayBuffer()),{filter:e=>e.name.endsWith('.json')&&e.originalSize<=32*1024*1024});const key=Object.keys(files).find(k=>k.endsWith('project.json')||k.endsWith('character.json'));if(!key)throw new Error('이 공방에서 저장한 프로젝트 ZIP을 선택해 주세요.');json=JSON.parse(strFromU8(files[key]));}else if(ext==='glb'){const buf=await file.arrayBuffer(),view=new DataView(buf);if(buf.byteLength<20||view.getUint32(0,true)!==0x46546c67||view.getUint32(4,true)!==2||view.getUint32(16,true)!==0x4e4f534a)throw new Error('올바른 GLB 파일이 아닙니다.');const size=view.getUint32(12,true);if(20+size>buf.byteLength)throw new Error('GLB 데이터가 끊어졌습니다.');const gltf=JSON.parse(new TextDecoder().decode(new Uint8Array(buf,20,size)));const meta=gltf.nodes?.find(n=>n.extras?.pixelPals)?.extras.pixelPals;if(!meta)throw new Error('이 공방에서 저장한 GLB만 다시 편집할 수 있습니다.');json={format:'pixel-pals',version:meta.version,state:meta.state};}else if(ext==='json'){json=JSON.parse(await file.text());}else throw new Error('JSON, ZIP, GLB 프로젝트를 선택해 주세요.');if(json.app==='10공방'&&json.version===1)json={format:'pixel-pals',version:1,state:convertSourceState(json.state)};if(json.format!=='pixel-pals'||json.version!==1)throw new Error('이 공방에서 만든 프로젝트 파일이 아닙니다.');json.state=validateState(json.state,defaults);if(json.studio!==undefined){const studio=json.studio;if(!studio||typeof studio.enabled!=='boolean'||!Array.isArray(studio.actors)||studio.actors.length>6)throw new Error('스튜디오 설정이 올바르지 않습니다.');studio.actors=studio.actors.map(actor=>{if(!actor||typeof actor!=='object')throw new Error('스튜디오 친구가 올바르지 않습니다.');for(const[k,min,max]of[['x',-3,3],['z',-2,2],['angle',-180,180],['scale',.5,1.4],['speed',.4,2]])if(typeof actor[k]!=='number'||!Number.isFinite(actor[k])||actor[k]<min||actor[k]>max)throw new Error('스튜디오 배치가 범위를 벗어났습니다.');if(!['shared',...enumRules.motion].includes(actor.motion))throw new Error('스튜디오 모션이 올바르지 않습니다.');return{...actor,state:validateState(actor.state,defaults)};});}return json;}
